try {
    const cfg = JSON.parse(msg.payload);
    const inverters = (cfg.inverters || []).filter(inv => inv.enabled !== false);
    const defaults = cfg.defaults || {};
    const merged = inverters.map(inv => ({
        ...inv,
        startPLC: inv.startPLC || defaults.startPLC || 40070,
        endPLC: inv.endPLC || defaults.endPLC || 40096
    }));
    global.set('inverterConfig', merged);
    node.status({ fill: 'green', shape: 'dot', text: `${merged.length} inverter(s) loaded` });
    msg.payload = {
        ok: true,
        count: merged.length,
        inverters: merged.map(i => ({ name: i.name, ip: i.ip, port: i.port, unitid: i.unitid }))
    };
    return msg;
} catch (err) {
    node.status({ fill: 'red', shape: 'ring', text: err.message });
    msg.payload = { ok: false, error: err.message };
    return msg;
}

// Bắt đầu batch mới: lưu danh sách inverter và index=0
const inverters = global.get('inverterConfig') || [];
if (!inverters.length) {
    node.status({ fill: 'yellow', shape: 'ring', text: 'no inverters' });
    return null;
}

const batchId = `batch-${Date.now()}`;
flow.set('_invBatch', {
    id: batchId,
    inverters: inverters,
    index: 0,
    results: [],
    total: inverters.length
});

// Gửi msg đổi kết nối cho inverter đầu tiên
const inv = inverters[0];
msg.payload = {
    connectorType: 'TCP',
    tcpHost: inv.ip,
    tcpPort: String(inv.port || 1502),
    unitId: inv.unitid || 1
};
msg.meta = {
    inv,
    startPLC: inv.startPLC || 40070,
    endPLC: inv.endPLC || 40096,
    ts: Math.floor(Date.now() / 1000),
    batchIndex: 0
};

node.status({ fill: 'blue', shape: 'dot', text: `batch start → ${inv.name}` });
return msg;

const meta = msg.meta;
if (!meta || !meta.inv) return null;
const startPLC = meta.startPLC || 40070;
const endPLC = meta.endPLC || 40096;
msg.payload = {
    fc: 3,
    unitid: meta.inv.unitid || 1,
    address: startPLC - 1,
    quantity: endPLC - startPLC + 1
};
return msg;

const meta = msg.meta || {};
const inv = meta.inv || {};
const basePLC = meta.startPLC || 40070;

function getRegs(msg) {
    if (Array.isArray(msg.payload)) return msg.payload;
    if (msg.payload && Array.isArray(msg.payload.data)) return msg.payload.data;
    if (msg.responseBuffer && Array.isArray(msg.responseBuffer.data)) return msg.responseBuffer.data;
    return null;
}
const regs = getRegs(msg);
if (!regs || regs.length === 0) {
    node.status({ fill: 'red', shape: 'ring', text: `No data: ${inv.name}` });
    msg.payload = { ok: false, error: `No data from ${inv.name}`, inv };
    msg._parseOk = false;
    return msg;
}

function idx(a) { return a - basePLC; }
function u16(a) { const i = idx(a); if (i < 0 || i >= regs.length) return null; return Number(regs[i]) & 0xFFFF; }
function s16(a) { const v = u16(a); if (v === null) return null; return v > 0x7FFF ? v - 0x10000 : v; }
function u32SS(a) { const lo = u16(a), hi = u16(a+1); if (lo===null||hi===null) return null; return hi*65536+lo; }
function sf(raw, s) { if (raw===null||s===null) return null; return raw * Math.pow(10, s); }
function rnd(v, d) { d=d||3; if (v===null||v===undefined||Number.isNaN(v)) return null; const m=Math.pow(10,d); return Math.round(v*m)/m; }

try {
    const cSF=s16(40076), vSF=s16(40083), pSF=s16(40085), fSF=s16(40087);
    const vrSF=s16(40091), pfSF2=s16(40093), eSF=s16(40096);
    const acW = sf(s16(40084), pSF);
    const acKW = acW===null ? null : acW/1000;
    const rVAr = sf(s16(40090), vrSF);
    const rKVAr = rVAr===null ? null : rVAr/1000;
    const pfPct = sf(s16(40092), pfSF2);
    const eWh = sf(u32SS(40094), eSF);

    const result = {
        name: inv.name, type: 'INVERTER', ip: inv.ip, unitid: inv.unitid, port: inv.port,
        ts: meta.ts || Math.floor(Date.now()/1000),
        model_did: u16(40070), model_length: u16(40071),
        Pinv_out_kw: rnd(acKW,3), Qinv_kvar: rnd(rKVAr,3),
        Ua_V: rnd(sf(u16(40080),vSF),2), Ub_V: rnd(sf(u16(40081),vSF),2), Uc_V: rnd(sf(u16(40082),vSF),2),
        Ia_A: rnd(sf(u16(40073),cSF),3), Ib_A: rnd(sf(u16(40074),cSF),3), Ic_A: rnd(sf(u16(40075),cSF),3),
        I_total_A: rnd(sf(u16(40072),cSF),3),
        frequency_Hz: rnd(sf(u16(40086),fSF),3),
        pf_percent: rnd(pfPct,3), power_factor: pfPct===null ? null : rnd(pfPct/100,4),
        Ainv_total_kWh: eWh===null ? null : rnd(eWh/1000,3),
        raw_registers: regs
    };
    global.set(inv.name, result);
    msg.payload = result;
    msg.topic = `inverter/${inv.name}`;
    msg._parseOk = true;
    node.status({ fill: 'green', shape: 'dot', text: `${inv.name}: ${rnd(acKW,1)||0}kW` });
    return msg;
} catch (err) {
    node.status({ fill: 'red', shape: 'ring', text: err.message });
    msg.payload = { ok: false, error: err.message, inv };
    msg._parseOk = false;
    return msg;
}

// Lưu kết quả, chuyển sang inverter tiếp theo hoặc kết thúc batch
const batch = flow.get('_invBatch');
if (!batch) return null;

// Lưu kết quả inverter vừa đọc
if (msg._parseOk && msg.payload) {
    batch.results.push(msg.payload);
}
batch.index++;
flow.set('_invBatch', batch);

if (batch.index < batch.total) {
    // Còn inverter tiếp → gửi flex-connector msg
    const inv = batch.inverters[batch.index];
    const nextMsg = {
        payload: {
            connectorType: 'TCP',
            tcpHost: inv.ip,
            tcpPort: String(inv.port || 1502),
            unitId: inv.unitid || 1
        },
        meta: {
            inv,
            startPLC: inv.startPLC || 40070,
            endPLC: inv.endPLC || 40096,
            ts: Math.floor(Date.now() / 1000),
            batchIndex: batch.index
        }
    };
    node.status({ fill: 'blue', shape: 'dot',
        text: `${batch.index+1}/${batch.total} → ${inv.name}` });
    // Output 1 → flex-connector (next inverter)
    return [nextMsg, null];
} else {
    // Hết inverter → Output 2 → summary
    const summary = {
        ts: Math.floor(Date.now() / 1000),
        total_inverters: batch.results.length,
        total_power_kW: 0,
        total_energy_kWh: 0,
        details: []
    };
    for (const r of batch.results) {
        summary.total_power_kW += (r.Pinv_out_kw || 0);
        summary.total_energy_kWh += (r.Ainv_total_kWh || 0);
        summary.details.push({ name: r.name, kW: r.Pinv_out_kw, kWh: r.Ainv_total_kWh });
    }
    summary.total_power_kW = Math.round(summary.total_power_kW * 1000) / 1000;
    summary.total_energy_kWh = Math.round(summary.total_energy_kWh * 1000) / 1000;
    global.set('INV_SUMMARY', summary);
    flow.set('_invBatch', null);
    node.status({ fill: 'green', shape: 'dot',
        text: `Done ${summary.total_inverters} INV | ${summary.total_power_kW}kW` });
    return [null, { payload: summary, topic: 'inverter/summary' }];
}
